import {gameToPixel} from './coordinates.js';

export function nextCaptureState(state){return state==='caught'?'complete':state==='complete'?'uncaught':'caught';}
export function captureMatches(state,filter){return filter==='all'||state===filter;}
export function pointInRegion(point,ring){
  let inside=false;
  for(let i=0,j=ring.length-1;i<ring.length;j=i++){
    const [ax,ay]=ring[j],[bx,by]=ring[i];
    const cross=(point.x-ax)*(by-ay)-(point.y-ay)*(bx-ax);
    if(Math.abs(cross)<1e-7&&point.x>=Math.min(ax,bx)-1e-7&&point.x<=Math.max(ax,bx)+1e-7&&point.y>=Math.min(ay,by)-1e-7&&point.y<=Math.max(ay,by)+1e-7)return true;
    if((ay>point.y)!==(by>point.y)&&point.x<(bx-ax)*(point.y-ay)/(by-ay)+ax)inside=!inside;
  }
  return inside;
}
export function regionAtPixel(point,mapName){
  if(mapName!=='Palpagos Islands'||!point||!Number.isFinite(point.x)||!Number.isFinite(point.y))return null;
  return surfaceRegions.find(region=>{
    const [minX,minY,maxX,maxY]=region.bounds;
    return point.x>=minX&&point.x<=maxX&&point.y>=minY&&point.y<=maxY&&pointInRegion(point,region.ring);
  })||null;
}
export function initCaptureTracker(onHabitat=()=>{}){
  const storageKey='palwaypoint-captures-v1', valid=new Set(palRoster.map(pal=>pal.id));
  function readCaptureProgress(){try{const saved=JSON.parse(localStorage.getItem(storageKey)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))return Object.fromEntries(Object.entries(saved).filter(([id,state])=>!['__proto__','constructor','prototype'].includes(id)&&['caught','complete'].includes(state)));}catch{}return {};}
  let progress=readCaptureProgress(),filter='all',availability=null;
  const list=document.querySelector('#pal-list'), search=document.querySelector('#pal-search');
  const summary=document.querySelector('#capture-summary'), filters=document.querySelector('#capture-filters');
  const labels={uncaught:'Uncaught',caught:'Caught',complete:'Complete (5/5 captures)'};
  const buttons=new Map();
  for(const value of ['all','uncaught','caught','complete']){
    const button=document.createElement('button');button.type='button';button.textContent=value==='all'?'All':value==='complete'?'Complete':labels[value];
    button.addEventListener('click',()=>{filter=value;render();});filters.append(button);buttons.set(value,button);
  }
  function render(){
    const states=Object.entries(progress).filter(([id])=>valid.has(id)).map(([,state])=>state), complete=states.filter(state=>state==='complete').length;
    summary.textContent=`Caught ${states.length}/${palRoster.length} · Complete ${complete}`;
    for(const [value,button] of buttons)button.setAttribute('aria-pressed',String(value===filter));
    const query=search.value.trim().toLowerCase();list.replaceChildren();
    for(const pal of palRoster){
      const state=progress[pal.id]||'uncaught';
      if(!captureMatches(state,filter)||!`${pal.name} ${pal.number}`.toLowerCase().includes(query))continue;
      const row=document.createElement('div');row.className='capture-row';
      const portrait=document.createElement('img');portrait.className='capture-portrait';portrait.src=`./icons/pals/${pal.id}.webp`;portrait.alt='';portrait.loading='lazy';
      const name=document.createElement('span');name.textContent=`#${pal.number} ${pal.name}`;
      if(availability){const a=availability.get(pal.id),label=document.createElement('small');label.className='pal-spawn-label';label.textContent=a?.field?`${a.field.toLocaleString('en-US')} field${a.special?' · '+a.special+' boss/dungeon':''}`:a?.special?`${a.special} boss/dungeon`:'No wild spawns recorded';name.append(label);}
      const button=document.createElement('button');button.type='button';button.className=`capture-sphere ${state}`;
      const next=nextCaptureState(state);button.setAttribute('aria-label',`${pal.name}: ${labels[state]}. Mark ${labels[next].toLowerCase()}`);button.title=`${labels[state]} — click to mark ${labels[next].toLowerCase()}`;
      const sphere=document.createElement('span');sphere.className='sphere-art';sphere.setAttribute('aria-hidden','true');button.append(sphere);
      button.addEventListener('click',()=>{
        if(next==='uncaught')delete progress[pal.id];else progress[pal.id]=next;
        const saveNote=document.querySelector('#capture-save-note');
        try{localStorage.setItem(storageKey,JSON.stringify(progress));saveNote.textContent='';saveNote.hidden=true;}
        catch{saveNote.textContent='Could not save in this browser. Progress lasts until this page closes.';saveNote.hidden=false;}
        render();document.querySelector(`[data-pal-id="${pal.id}"]`)?.focus();
      });
      const habitat=document.createElement('button');habitat.type='button';habitat.className='pal-habitat-button';habitat.textContent='Map';
      habitat.setAttribute('aria-label',`View ${pal.name} habitat`);habitat.addEventListener('click',()=>onHabitat(pal.id,pal.name));
      button.dataset.palId=pal.id;row.append(portrait,name,habitat,button);list.append(row);
    }
    if(!list.children.length){const empty=document.createElement('p');empty.className='capture-help';empty.textContent='No Pals match these filters.';list.append(empty);}
  }
  for(const view of ['locations','pals'])document.querySelector(`#${view}-tab`).addEventListener('click',()=>{
    for(const name of ['locations','pals']){document.querySelector(`#${name}-view`).hidden=name!==view;document.querySelector(`#${name}-tab`).setAttribute('aria-pressed',String(name===view));}
  });
  window.addEventListener('storage',event=>{
    if(event.key!==storageKey&&event.key!==null)return;
    progress=readCaptureProgress();
    render();
  });
  search.addEventListener('input',render);render();
  return {setAvailability(value){availability=value;render();}};
}

export const markerCategories=[];
export const categoryById=new Map();

export async function loadCategories(){
  const response=await fetch('./marker-categories.json?v=recovery-2');
  if(!response.ok)throw new Error('Marker categories unavailable');
  const categories=await response.json();
  markerCategories.splice(0,markerCategories.length,...categories);
  categoryById.clear();
  for(const category of categories)categoryById.set(category.id,category);
}

export async function loadMarkers(config){
  const response=await fetch(`${config.markers}${config.markers.includes('?')?'&':'?'}v=native-regions-1`);
  if(!response.ok)throw new Error('Marker locations unavailable');
  const records=await response.json();
  return records.map(([category,name,worldX,worldY,detail,icon,level,loot,legacyId,sourceId,metadata])=>{
    const gameX=(worldY-158000)/459;
    const gameY=(worldX+123888)/459;
    const id=legacyId||`${config.name}:${category}:${worldX}:${worldY}`;
    return {id,category,name,detail,icon,level,loot,sourceId,metadata,gameX,gameY,pixel:gameToPixel(gameX,gameY,config.calibration)};
  });
}

